question:
An octahedron consists of two square-based pyramids glued together along their square bases to form a polyhedron with eight faces. Imagine an ant that begins at the top vertex and walks to one of the four adjacent vertices that he randomly selects and calls vertex A. From vertex A, he will then walk to one of the four adjacent vertices that he randomly selects and calls vertex B. What is the probability that vertex B will be the bottom vertex? Express your answer as a common fraction.

[asy]
draw((-10,0)--(10,0)--(3,-15)--cycle);
draw((-10,0)--(10,0)--(3,15)--cycle);
draw((10,0)--(17,7)--(3,-15)--(17,7)--(3,15));
draw((-3,7)--(3,15)--(-3,7)--(17,7)--(-3,7)--(-10,0)--(-3,7)--(3,-15),dashed);
[/asy]

Milton spilled some ink on his homework paper. He can't read the coefficient of $x$, but he knows that the equation has two distinct negative, integer solutions. What is the sum of all of the distinct possible integers that could be under the ink stain?

[asy]
draw((0,0)--(3,0)--(3,3)--(0,3)--cycle);
fill((0,0)--(3,0)--(3,3)--(0,3)--cycle,black);
label("$x+36=0$",(3,1.5),E);
label("$x^{2}+$",(0,1.5),W);
[/asy]

Three coplanar squares with sides of lengths two, four and six units, respectively, are arranged side-by-side, as shown so that one side of each square lies on line $AB$ and a segment connects the bottom left corner of the smallest square to the upper right corner of the largest square. What is the area of the shaded quadrilateral? [asy] size(150); defaultpen(linewidth(0.9)+fontsize(10));
fill((2,0)--(6,0)--(6,3)--(2,1)--cycle,gray(0.8));
draw(scale(2)*unitsquare);
draw(shift(2,0)*scale(4)*unitsquare);
draw(shift(6,0)*scale(6)*unitsquare);
draw((0,0)--(12,6));

real d = 1.2; pair d2 = (0.9,0);
pair A = (-d,0), B = (12+d,0); dot(A,linewidth(3)); dot(B,linewidth(3)); label("A",A,(0,-1.5)); label("B",B,(0,-1.5)); draw(A-d2--B+d2,Arrows(4));
label("2",(1,2.7)); label("4",(4,4.7)); label("6",(9,6.7));
[/asy]

Below is a portion of the graph of a function, $y=h(x)$:

[asy]
import graph; size(8cm); real lsf=0.5; pen dps=linewidth(0.7)+fontsize(10); defaultpen(dps); pen ds=black; real xmin=-4.25,xmax=4.25,ymin=-7.25,ymax=6.25;

pen cqcqcq=rgb(0.75,0.75,0.75);

/*grid*/ pen gs=linewidth(0.7)+cqcqcq+linetype("2 2"); real gx=1,gy=1;
for(real i=ceil(xmin/gx)*gx;i<=floor(xmax/gx)*gx;i+=gx) draw((i,ymin)--(i,ymax),gs); for(real i=ceil(ymin/gy)*gy;i<=floor(ymax/gy)*gy;i+=gy) draw((xmin,i)--(xmax,i),gs);

Label laxis; laxis.p=fontsize(10);

xaxis("",xmin,xmax,Ticks(laxis,Step=1.0,Size=2,NoZero),Arrows(6),above=true); yaxis("",ymin,ymax,Ticks(laxis,Step=1.0,Size=2,NoZero),Arrows(6),above=true);
real f1(real x){return 4.125-(x+0.5)^2/2;}
draw(graph(f1,-4.25,4.25),linewidth(1));
clip((xmin,ymin)--(xmin,ymax)--(xmax,ymax)--(xmax,ymin)--cycle);
label("$y=h(x)$",(4.5,-6),E);
[/asy]

If the graph of $y=h(x-3)$ is drawn on the same set of axes as the graph above, then the two graphs intersect at one point. What is the sum of the coordinates of that point?

A portion of the graph of a quadratic function $f(x)$ is shown below.

Let $g(x)=-f(x)$ and $h(x)=f(-x)$. If $a$ is the number of points where the graphs of $y=f(x)$ and $y=g(x)$ intersect, and $b$ is the number of points where the graphs of $y=f(x)$ and $y=h(x)$ intersect, then what is $10a+b$?

[asy]
size(150);
real ticklen=3;
real tickspace=2;

real ticklength=0.1cm;
real axisarrowsize=0.14cm;
pen axispen=black+1.3bp;
real vectorarrowsize=0.2cm;
real tickdown=-0.5;
real tickdownlength=-0.15inch;
real tickdownbase=0.3;
real wholetickdown=tickdown;
void rr_cartesian_axes(real xleft, real xright, real ybottom, real ytop, real xstep=1, real ystep=1, bool useticks=false, bool complexplane=false, bool usegrid=true) {

import graph;

real i;

if(complexplane) {

label("$\textnormal{Re}$",(xright,0),SE);

label("$\textnormal{Im}$",(0,ytop),NW);

} else {

label("$x$",(xright+0.4,-0.5));

label("$y$",(-0.5,ytop+0.2));

}

ylimits(ybottom,ytop);

xlimits( xleft, xright);

real[] TicksArrx,TicksArry;

for(i=xleft+xstep; i<xright; i+=xstep) {

if(abs(i) >0.1) {

TicksArrx.push(i);

}

}

for(i=ybottom+ystep; i<ytop; i+=ystep) {

if(abs(i) >0.1) {

TicksArry.push(i);

}

}

if(usegrid) {

xaxis(BottomTop(extend=false), Ticks("%", TicksArrx ,pTick=gray(0.22),extend=true),p=invisible);//,above=true);

yaxis(LeftRight(extend=false),Ticks("%", TicksArry ,pTick=gray(0.22),extend=true), p=invisible);//,Arrows);

}

if(useticks) {

xequals(0, ymin=ybottom, ymax=ytop, p=axispen, Ticks("%",TicksArry , pTick=black+0.8bp,Size=ticklength), above=true, Arrows(size=axisarrowsize));

yequals(0, xmin=xleft, xmax=xright, p=axispen, Ticks("%",TicksArrx , pTick=black+0.8bp,Size=ticklength), above=true, Arrows(size=axisarrowsize));

} else {

xequals(0, ymin=ybottom, ymax=ytop, p=axispen, above=true, Arrows(size=axisarrowsize));

yequals(0, xmin=xleft, xmax=xright, p=axispen, above=true, Arrows(size=axisarrowsize));

}
};
rr_cartesian_axes(-2,5,-2,4);
real f(real x) {return (x-1)*(x-3)/2;}
draw(graph(f,-1,5,operator ..), red);
[/asy]

Find the number of square units in the area of the triangle.

[asy]size(125);
draw( (-10,-2) -- (2,10), Arrows);
draw( (0,-2)-- (0,10) ,Arrows);
draw( (5,0) -- (-10,0),Arrows);

label("$l$",(2,10), NE);
label("$x$", (5,0) , E);
label("$y$", (0,-2) , S);
filldraw( (-8,0) -- (0,8) -- (0,0) -- cycle, lightgray);
dot( (-2, 6)); dot( (-6, 2)); label( "(-2, 6)", (-2, 6), W, fontsize(10)); label( "(-6, 2)", (-6, 2), W, fontsize(10));
[/asy]

In the diagram shown, $\overrightarrow{OA}\perp\overrightarrow{OC}$ and $\overrightarrow{OB}\perp\overrightarrow{OD}$. If $\angle{AOD}$ is 3.5 times $\angle{BOC}$, what is $\angle{AOD}$? [asy]
unitsize(1.5cm);
defaultpen(linewidth(.7pt)+fontsize(10pt));
dotfactor=4;

pair O=(0,0), A=dir(0), B=dir(50), C=dir(90), D=dir(140);
pair[] dots={O,A,B,C,D};

dot(dots);
draw(O--1.2*D,EndArrow(4));
draw(O--1.2*B,EndArrow(4));
draw(O--1.2*C,EndArrow(4));
draw(O--1.2*A,EndArrow(4));

label("$D$",D,SW);
label("$C$",C,W);
label("$B$",B,E);
label("$A$",A,N);
label("$O$",O,S);
[/asy]

Spinners $A$ and $B$ are spun. On each spinner, the arrow is equally likely to land on each number. What is the probability that the product of the two spinners' numbers is even?  Express your answer as a common fraction. [asy]
/* AMC8 2004 #21 Problem */
draw(circle((0,0), 2));
draw(circle((6,0), 2));
draw((-2,0)--(2,0));
draw((0,-2)--(0,2));
path p=(0,0)--(0,2);
draw(shift(6,0)*p);
draw(shift(6,0)*rotate(120)*p);
draw(shift(6,0)*rotate(240)*p);
label(scale(0.6)*"1", (-1,1));
label(scale(0.6)*"2", (1,1));
label(scale(0.6)*"3", (1,-1));
label(scale(0.6)*"4", (-1,-1));
label(scale(0.6)*"1", (5,.75));
label(scale(0.6)*"2", (7,.75));
label(scale(0.6)*"3", (6,-1));
draw((0,0)--(1.5,.5), EndArrow);
draw(shift(6,0)*rotate(45)*((0,0)--(1.5,.5)), EndArrow);
[/asy]

Let \[f(x) = \left\{
\begin{array}{cl}
2x + 7 & \text{if } x < -2, \\
-x^2 - x + 1 & \text{if } x \ge -2.
\end{array}
\right.\]Find the sum of all values of $x$ such that $f(x) = -5.$

Find the area of triangle $ABC$ below.


[asy]

unitsize(1inch);

pair P,Q,R;

P = (0,0);

Q= (sqrt(3),0);

R = (0,1);

draw (P--Q--R--P,linewidth(0.9));

draw(rightanglemark(Q,P,R,3));

